using Polyline = System.Windows.Shapes.Polyline;
using System;using System.Collections.Generic;using System.Linq;using System.Reflection;using System.IO;using System.Web.Script.Serialization;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Automation;using NetworkRescue;
class NativeWindowTests {
 static int assertions;static JavaScriptSerializer json=new JavaScriptSerializer();static NativeWindow window;static List<KeyValuePair<string,Dictionary<string,object>>> commands=new List<KeyValuePair<string,Dictionary<string,object>>>();
 static void Assert(bool b,string text){assertions++;if(!b)throw new Exception("FAIL: "+text);}
 static IEnumerable<DependencyObject> Walk(DependencyObject item){yield return item;for(int i=0;i<VisualTreeHelper.GetChildrenCount(item);i++)foreach(var x in Walk(VisualTreeHelper.GetChild(item,i)))yield return x;}
 static FrameworkElement Root {get{return (FrameworkElement)window.Content;}}
 static void Layout(){Root.Measure(new Size(1280,860));Root.Arrange(new Rect(0,0,1280,860));Root.UpdateLayout();}
 static void Send(object value){window.Receive(json.Serialize(value));Layout();}
 static Button Button(string id){return Walk(Root).OfType<Button>().First(b=>AutomationProperties.GetAutomationId(b)==id);}
 static void Click(string id){var b=Button(id);Assert(b.IsEnabled,"enabled "+id);b.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));Layout();}
 static object Field(string name){return typeof(NativeWindow).GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(window);}
 static bool Contains(string text){return Walk(Root).OfType<TextBlock>().Any(t=>t.Text.Contains(text))||Walk(Root).OfType<TextBox>().Any(t=>t.Text.Contains(text));}
 static void Header(){Assert(Button("beginner").ActualWidth>0&&Button("advanced").ActualWidth>0,"both header modes present");Assert(Button("beginner").TranslatePoint(new Point(0,0),Root).Y<100,"mode control fixed in header");Assert(Button("advanced").TranslatePoint(new Point(Button("advanced").ActualWidth,0),Root).X<=Root.ActualWidth,"header mode does not clip at right edge");}
 static void FooterNavigation(){var settings=Button("nav-settings");var help=Button("nav-help");Assert(settings.ActualWidth>=32&&settings.ActualHeight>=32&&help.ActualWidth>=32&&help.ActualHeight>=32,"footer icon hit targets at least 32px");Assert(settings.Focusable&&settings.IsTabStop&&help.Focusable&&help.IsTabStop,"footer icons keyboard focusable");Assert((string)settings.ToolTip==NativeUiText.LocalText("navSettings")&&AutomationProperties.GetName(settings)==NativeUiText.LocalText("navSettings")&&(string)help.ToolTip==NativeUiText.LocalText("navHelp")&&AutomationProperties.GetName(help)==NativeUiText.LocalText("navHelp"),"localized footer icon tooltips and automation names");Assert(settings.Parent==help.Parent&&settings.Parent is Grid,"footer icons share mode-label row");var row=(Grid)settings.Parent;Assert(row.Children.OfType<TextBlock>().Any(t=>t.Text==NativeUiText.LocalText((string)Field("mode"))),"footer row retains current mode label");Assert(settings.TranslatePoint(new Point(0,0),Root).Y>Root.ActualHeight-160&&Math.Abs(settings.TranslatePoint(new Point(0,0),Root).Y-help.TranslatePoint(new Point(0,0),Root).Y)<1,"utilities anchored together at sidebar bottom");Assert(settings.TranslatePoint(new Point(settings.ActualWidth,0),Root).X<=232&&help.TranslatePoint(new Point(help.ActualWidth,0),Root).X<=232,"footer icons remain inside sidebar");var nav=(StackPanel)Field("navigation");Assert(!Walk(nav).OfType<Button>().Any(b=>new[]{"nav-settings","nav-help","nav-history"}.Contains(AutomationProperties.GetAutomationId(b))),"main navigation contains only diagnosis and toolbox items");}
 static void Idle(){Send(new{type="busy",operation=(string)null});Assert(((TextBlock)Field("footer")).Text=="","idle footer stays empty; Ready belongs beside H1");}
 static void Report(){string[] ids={"Hardware","Connection","DhcpService","Dns","Hosts","Proxy","Winsock","Http"};var items=ids.Select(id=>new{Id=id,Title=id,State=Array.IndexOf(ids,id)%4,Summary="fixture summary",Detail="FIXTURE_TECHNICAL_ONLY "+id,Actions=id=="Proxy"?new object[]{new{Id="DisableProxy",AdapterId="",Title="fixture repair",Description="fixture description",Impact="fixture impact",Suggested=true}}:new object[0]}).ToArray();Send(new{type="report",report=new{Timestamp=DateTime.UtcNow,InternetAvailable=false,Summary="fixture summary",Items=items,SpecialChecks=new[]{new{Title="PAC / WPAD",State=3,Summary="fixture-special-summary",Detail="SPECIAL_PRIVATE_TECH_ONLY"},new{Title="WinHTTP",State=3,Summary="fixture-special-summary",Detail="SPECIAL_PRIVATE_TECH_ONLY"}}}});}
 static void Screenshot(string file){Layout();RenderTargetBitmap bitmap=new RenderTargetBitmap(1280,860,96,96,PixelFormats.Pbgra32);bitmap.Render(Root);PngBitmapEncoder png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var s=File.Create(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,file)))png.Save(s);}
 static object Invoke(string name,params object[] args){return typeof(NativeWindow).GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(window,args);}
 static CheckBox Check(string id){return Walk(Root).OfType<CheckBox>().Single(c=>AutomationProperties.GetAutomationId(c)==id);}
 static IList<object> SpeedPoints(){return ((System.Collections.IEnumerable)Field("speedPoints")).Cast<object>().ToList();}
 static double PointValue(object point,string field){return Convert.ToDouble(point.GetType().GetField(field).GetValue(point));}
 static void SpeedPacket(double seconds,long down,long up){Send(new{type="speed",result=new{ElapsedSeconds=seconds,DownloadBytes=down,UploadBytes=up,DownloadMbps=42.0,UploadMbps=24.0,LatencyMs=18.0,State="fixture transfer",Detail="fixture details",Node="public fixture",Route="fixture route"}});}
 static T ById<T>(string id) where T:DependencyObject{return Walk(Root).OfType<T>().Single(x=>AutomationProperties.GetAutomationId(x)==id);}
 static void ScreenshotAt(string file,int width,int height){Root.Measure(new Size(width,height));Root.Arrange(new Rect(0,0,width,height));Root.UpdateLayout();RenderTargetBitmap bitmap=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);bitmap.Render(Root);PngBitmapEncoder png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,file)))png.Save(stream);}
 static IList<object> SessionRows(){return ((System.Collections.IEnumerable)Field("monitorSessionTargets")).Cast<object>().ToList();}
 static IList<object> MonitorRows(){return ((System.Collections.IEnumerable)Field("monitorTargets")).Cast<object>().ToList();}
 static object RowField(object row,string name){return row.GetType().GetField(name).GetValue(row);}
 static void SelectTag(string id,string tag){var combo=ById<ComboBox>(id);combo.SelectedItem=combo.Items.Cast<ComboBoxItem>().First(i=>(string)i.Tag==tag);Layout();}
 static void OfficialUpdateSourceChecks()
 {
  NativeWindow previous=window;window=new NativeWindow();window.CommandRequested+=(c,v)=>commands.Add(new KeyValuePair<string,Dictionary<string,object>>(c,v));
  string directory=Path.Combine(Path.GetTempPath(),"NetworkRescueUpdateMigration-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(directory);string path=Path.Combine(directory,"settings.json");
  try
  {
   var flags=BindingFlags.Instance|BindingFlags.NonPublic;var controller=(NativeController)System.Runtime.Serialization.FormatterServices.GetUninitializedObject(typeof(NativeController));
   typeof(NativeController).GetField("view",flags).SetValue(controller,window);typeof(NativeController).GetField("settingsRoot",flags).SetValue(controller,directory);typeof(NativeController).GetField("json",flags).SetValue(controller,new JavaScriptSerializer());
   string[] inputs={null,"{}",json.Serialize(new{updateRepository=""}),json.Serialize(new{updateRepository=" \t "}),json.Serialize(new{updateRepository=" custom-owner/project "}),json.Serialize(new{updateRepository="https://invalid.example/repo"})};
   string[] expected={UpdateService.DefaultRepository,UpdateService.DefaultRepository,UpdateService.DefaultRepository,UpdateService.DefaultRepository,"custom-owner/project","https://invalid.example/repo"};
   for(int i=0;i<inputs.Length;i++)
   {
    if(inputs[i]==null)File.Delete(path);else File.WriteAllText(path,inputs[i]);typeof(NativeController).GetField("updateRepository",flags).SetValue(controller,UpdateService.DefaultRepository);
    typeof(NativeController).GetMethod("ReadSettings",flags).Invoke(controller,null);string source=(string)typeof(NativeController).GetField("updateRepository",flags).GetValue(controller);
    Assert(source==expected[i]&&typeof(NativeController).GetField("operation",flags).GetValue(controller)==null,"settings migration selects official defaults, retains custom/invalid sources and starts no operation: "+i);
    Assert(inputs[i]==null?!File.Exists(path):File.ReadAllText(path)==inputs[i],"reading update settings does not rewrite existing user configuration: "+i);
    int before=commands.Count;I18n.SetLanguage("zh-CN");Send(new{type="init",language="zh-CN",mode="advanced",version="1.0.0",updateRepository=source});Click("nav-settings");
    Assert(((TextBox)Field("repositoryInput")).Text==expected[i]&&!commands.Skip(before).Any(c=>c.Key=="checkUpdates"||c.Key=="openUpdate"),"initial source is visible without automatically checking or opening releases: "+i);
   }
  }
  finally{File.Delete(path);Directory.Delete(directory);window.Close();window=previous;}
 }
