 static double Lum(Color color){return new[]{color.R,color.G,color.B}.Select(v=>{double c=v/255.0;return c<=.03928?c/12.92:Math.Pow((c+.055)/1.055,2.4);}).Zip(new[]{.2126,.7152,.0722},(v,w)=>v*w).Sum();}
 static double Contrast(Brush first,Brush second){double a=Lum(((SolidColorBrush)first).Color),b=Lum(((SolidColorBrush)second).Color);return (Math.Max(a,b)+.05)/(Math.Min(a,b)+.05);}
